	void BlockBlockContact::updateConnectors()
	{
		if (separation <= 0.0f)
		{
			if (inKernel())
			{
				matched.resize(connectors.size(), false);
				for (int i = 0; i < connectors.size(); ++i)
					matched[i] = false;

				if (planeContact)
					computePlaneContact();
				else
					loadGeoPairEdgeEdge(0, 1, feature[0] - 6, feature[1] - 6);

				deleteUnmatchedConnectors();
			}
		}
		else
		{
			deleteAllConnectors();
			feature[0] = -1;
			feature[1] = -1;
		}
	}
